import subprocess
def _ensure_cutlass_include():
    cutlass_home = os.environ.get("CUTLASS_HOME")
    if cutlass_home and os.path.exists(os.path.join(cutlass_home, "include", "cute", "tensor.hpp")):
        return os.path.join(cutlass_home, "include")
    cache_dir = os.path.join(os.path.expanduser("~"), ".cache", "cutlass_cute_repo")
    header_path = os.path.join(cache_dir, "include", "cute", "tensor.hpp")
    if not os.path.exists(header_path):
        os.makedirs(os.path.dirname(cache_dir), exist_ok=True)
        if os.path.exists(cache_dir) and not os.path.exists(header_path):
            pass
        if not os.path.exists(cache_dir) or not os.listdir(cache_dir):
            subprocess.run(
                ["git", "clone", "--depth", "1", "https://github.com/NVIDIA/cutlass.git", cache_dir],
                check=True,
            )
