        float4 v = in4[idx];
        float4 r;
        r.x = fast_tanhf(v.x);
        r.y = fast_tanhf(v.y);
        r.z = fast_tanhf(v.z);
        r.w = fast_tanhf(v.w);
        out4[idx] = r;
    }
    if (tid < tail) {
        Tensor gIn  = make_tensor(make_gmem_ptr(in_tail),  make_shape(tail_start + tail));
        Tensor gOut = make_tensor(make_gmem_ptr(out_tail), make_shape(tail_start + tail));
        int idx = tail_start + tid;
        gOut(idx) = fast_tanhf(gIn(idx));
