__global__ void cute_tanh_vec4_kernel(const float4* __restrict__ in,
                                       float4* __restrict__ out,
                                       int n4)
{
    // Simple, low-register-pressure grid-stride loop over float4 elements.
    // Removing the previous manual 4x inner unroll reduces per-iteration
    // bounds checks/branches and register usage, while the compiler is
    // still free to unroll the loop via #pragma unroll for ILP. Global
    // memory accesses remain fully coalesced (contiguous float4 reads/writes).
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    #pragma unroll 4
    for (int idx = tid; idx < n4; idx += stride) {
        float4 v = in[idx];
        float4 r;
        r.x = fast_tanhf(v.x);
        r.y = fast_tanhf(v.y);
        r.z = fast_tanhf(v.z);
        r.w = fast_tanhf(v.w);
        out[idx] = r;
    }
}
__global__ void cute_tanh_tail_kernel(const float* __restrict__ in,
                                       float* __restrict__ out,
                                       int start,
                                       int n)
{
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int idx = start + tid;
    Tensor gIn  = make_tensor(make_gmem_ptr(in),  make_shape(n));
    Tensor gOut = make_tensor(make_gmem_ptr(out), make_shape(n));
    if (idx < n) {
        gOut(idx) = fast_tanhf(gIn(idx));
    }
}
